#include "ksPanelToggleCalls.h"
#include "ksControllerBoundary.h"
#include <stdexcept>
namespace ks{namespace{PanelTogglePartialTest partialTest=nullptr;using T=PanelToggleTask;using S=T::Stage;using K=T::Kind;struct Point{unsigned location,length;};Point point(const T&t){unsigned delta=t.kind()==K::FirstBit?0x1e:0;switch(t.stage()){case S::Hold:return{0x826 + delta,2};case S::ReadMirror:return{0x828 + delta,6};case S::MaskMirror:return{0x82e + delta,2};case S::ReadInput:return{0x830 + delta,2};case S::AdmitInput:return{0x832 + delta,2};case S::Enable:return{0x834 + delta,2};case S::WriteMirror:return{0x836 + delta,6};case S::Dispatch:return{0x83c + delta,4};case S::AwaitPublish:case S::Restore:return{0x840 + delta,2};case S::Finish:return{0x842 + delta,2};default:throw std::runtime_error("Invalid panel toggle stage");}}}
bool PanelToggleCalls::step(ControllerCpu&h){using namespace controllerDetail;unsigned pc=unsigned(h.getPC());std::optional<Call>*selected=nullptr;for(auto&c:calls)if(c&&c->token-c->depth==h.getSP()){selected=&c;break;}if(pc==0x826||pc==0x844){if(selected)throw std::runtime_error("Overlapping panel toggle");for(auto&c:calls)if(!c){selected=&c;break;}if(!selected)throw std::runtime_error("Panel toggle capacity");selected->emplace(pc==0x826?K::SecondBit:K::FirstBit,h.getSP());++started;}if(!selected||point((**selected).task).location!=pc){if(partialTest&&partialTest(h)){++partialEntries;return true;}return false;}auto&t=(**selected).task;if(t.awaiting())t.resumeChild();auto stage=t.stage();auto before=h.cycles;Boundary f(h,pc,point(t).length);auto&v=h.regs;auto cost=t.nextClocks();t.advanceBefore(cost,[&](T::Read r){return r==T::Read::Input?uint8_t(v[6].rl):uint8_t(h.read8(0xffec20));},[&](uint8_t value){f.store8(0xffec20,int8_t(value));});switch(stage){case S::Hold:f.push(v[0].r);(**selected).depth+=2;break;case S::ReadMirror:f.move(v[0].rl,int8_t(t.mirror()));break;case S::MaskMirror:v[0].rl&=t.kind()==K::SecondBit?1:2;value(h,v[0].rl);break;case S::ReadInput:f.move(v[6].rl,v[6].rl);break;case S::Enable:v[0].rl|=t.kind()==K::SecondBit?2:1;value(h,v[0].rl);break;case S::Dispatch:f.call(0x6d0);h.pc=h.makepc(f.next);break;case S::Restore:f.pop(v[0].r);(**selected).depth-=2;break;case S::Finish:f.ret();h.pc=h.makepc(f.next);selected->reset();++completed;break;default:break;}if(stage!=S::Dispatch&&stage!=S::Finish)h.pc=h.makepc(point(t).location);if(h.cycles-before!=cost)throw std::runtime_error("Panel toggle clocks differ");return true;}}

namespace ks{void setPanelTogglePartialForTests(PanelTogglePartialTest fn){partialTest=fn;}}
